-- 2254 🏋️ Exercises from the book "tactical-periodization-a-proven-successful-training-model" into the exercise catalog (mig 2191).
-- Every practice the book sets out, in OUR OWN WORDS, with app page numbers
-- (the diagram is the book page).  Written by scripts/exercises/sync.py load.
-- Re-runnable: clears this book's exercises first.
BEGIN;
DELETE FROM exercises WHERE book_id = (SELECT id FROM coaching_books WHERE slug = 'tactical-periodization-a-proven-successful-training-model');
INSERT INTO exercises (title, category_id, opposition, moment, source_id, book_id, page_from, page_to, source_ref, coach,
  objective, setup, procedure, rules, progressions, coaching_points, players_text, min_players, max_players,
  area_text, area_length_m, area_width_m, duration_min, has_goals, has_keepers, directional, age_text, sort_order)
SELECT v.t, c.id, v.opp, v.m, b.source_id, b.id, v.pf::int, v.pt::int, v.ref, v.coach, v.obj, v.setup, v.proc, v.rules, v.prog, v.cp,
  v.players, v.mn::int, v.mx::int, v.area, v.len::real, v.wid::real, v.dur::real, v.goals::boolean, v.gk::boolean, v.dir::boolean, v.age, v.so
FROM (VALUES
  ('4v4+2 possession in diamond midfield shape', 'possession', 'overload', 'in_possession', 66, 66, '4 v 4 (+2) ''Diamond'' Midfield (Correct Configuration)', NULL, 'Keep the ball and circulate it using the same diamond midfield shape the team uses in its 4-4-2 match formation.', 'Rectangle around the centre circle; two teams of four plus two yellow neutral players supporting from the outside at either end. Each team of four sets up as a diamond (base, two sides, tip).', 'Team in possession circulates among its four and plays out to a yellow neutral, who returns it; the other four try to win it. Turnover swaps roles.', 'Neutrals play for the team with the ball from outside the area.', 'Book contrasts it with a ''box'' arrangement of the four (incorrect configuration) which produces actions and links that do not match the diamond game model - use the diamond.', 'Shape must mirror the match structure so the right adaptations and passing relationships emerge; design structure carefully.', '4v4+2', 10, 10, NULL, NULL, NULL, NULL, false, false, false, NULL, 10),
  ('5v5 build-up through 2-1-2 to mini goals', 'small_sided_game', 'opposed', 'in_possession', 67, 67, '5 v 5 Build Up Play with 2-1-2 Structure (from 4-3-3)', NULL, 'Build from the centre backs through the defensive midfielder into the attacking midfielders, replicating a 4-3-3 build-up unit.', 'Reduced pitch with two mini goals at each end; blues in a 2-1-2 (two CBs, one DM, two AMs), reds opposite; coach with balls on the halfway side.', 'Coach feeds a blue centre back; blues work the ball via the DM to an AM and score in either of the two far mini goals. If reds win it they attack the blues'' two mini goals quickly.', 'Fixed positions and roles; score in either of two mini goals.', NULL, 'Defined positional references make the desired behaviour (playing into the midfielders) appear far more often than in a match; without roles the behaviour is rare and wrong habits can form.', '5v5', 10, 11, NULL, NULL, NULL, NULL, true, false, true, NULL, 20),
  ('6+GK v 5 playing out from the back', 'phase_of_play', 'opposed', 'in_possession', 69, 69, 'Specific (Tactical) Practice Example: Playing Out from the Back in a 6 (+GK) v 5 Practice', 'Mourinho principle (Oliveira)', 'Play out from the back in the defensive third and advance the ball to a midfielder or overlapping full back.', 'Defensive half of the pitch with the full-size goal; blues GK + four defenders + two central midfielders against three forwards and two central midfielders (reds). Three mini goals spread along the halfway line in the diagram.', 'GK or coach starts with a pass to a defender; blues coordinate to move the ball forward to a midfielder (diagonal pass) or to a full back driving forward. Reds press and try to stop passes into the blue midfielders.', NULL, NULL, 'Coach must intervene when a player abandons the principle (e.g. full back pressed and clears long instead of finding a free teammate) - otherwise the practice builds habits that contradict the game model.', '6+GK v 5', 12, 12, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 30),
  ('11v4 build-up through five channels', 'phase_of_play', 'overload', 'in_possession', 192, 192, 'Tuesday Practice 1 (Sectorial)', NULL, 'Playing out from the back and circulating the ball across all channels before attacking the final zone, as active recovery.', 'Large area split into 5 vertical channels with a marked final zone at the far end; a full team of blues plus GK against 4 red defenders.', 'Every rep starts with the goalkeeper, who chooses the first pass; blues use set passing and movement patterns to get the ball into all 5 channels before entering the final zone. Patterns change each set, with a free final set.', 'Ball must visit all 5 channels before entering the final zone. Reds defend as a compact back four and may leave the final zone at any time; if reds win it they hit a long pass to the GK for 1 point and play restarts from the GK.', 'Change the passing pattern every set; last set free choice.', 'Correct body shape to receive, timed runs, triangles for passing angles, mix short and long passes.', '14 outfield players + 1 GK (10+GK v 4)', 15, 15, NULL, NULL, NULL, 15.0, false, true, true, NULL, 40),
  ('11v8 build-up to play in behind', 'phase_of_play', 'overload', 'in_possession', 193, 193, 'Tuesday Practice 2 (Intersectorial)', NULL, 'Building from the back and playing passes in behind the defensive line.', '60 x 65 m area with 5 vertical channels; blues build from their goalkeeper against 8 reds; small goals on the blues'' end line.', 'Like Practice 1 but the blues now have to pass into all 5 channels before they may score, and use set passing and movement patterns to break in behind.', 'The pass in behind the line must go from one channel into another, and all final passes must also cross from one channel to another.', 'Change passing patterns every set, free final set.', 'Timed runs in behind, supporting body shape, triangles, mix of short and long passes; reds stay compact in width and depth.', '18 outfield players + 1 GK', 19, 19, '60 x 65 metres / 65 x 70 yards', 65.0, 60.0, 15.0, true, true, true, NULL, 50),
  ('Three-zone build-up v compact 2-4-1', 'phase_of_play', 'overload', 'in_possession', 194, 194, 'Tuesday Practice 3 (Intersectorial)', NULL, 'Build-up and positional play against a defending team working on compactness in width and depth.', 'Area split into 3 equal horizontal zones (defence, midfield, attack) with vertical lines as positional guides; blues in a 4-2-3-1 or 4-3-3 against reds in a 2-4-1, both with keepers.', 'Each rep starts with the blue goalkeeper; blues build up through the zones and try to score while reds shift and squeeze together as a unit.', 'Blues max 2 touches in zones 1 and 2, unlimited in zone 3; offside only in zone 3; reds unlimited touches; both teams must keep within set zone limits (partly hidden on page).', NULL, 'Switch play to create overloads; reds shift across, give cover, press at the right speed and angle and close passing lanes.', '17 outfield players + 2 GKs (10 v 7 + GKs)', 19, 19, '50 x 65 metres / 55 x 70 yards', 65.0, 50.0, 12.0, true, true, true, NULL, 60),
  ('Two-square press and switch game', 'transition', 'opposed', 'to_defend', 196, 197, 'Wednesday Practice 1 (Sectorial)', NULL, 'Pressing as a unit to win the ball fast, and switching play quickly to the other square after a turnover.', 'Two 25 x 25 m squares with a 7 m neutral zone between; 4 teams of 4 - blues and reds in different squares, a pressing team (yellows) in with one of them, and outside white players on the sides of the squares.', 'The team in possession tries to make 4 passes with help from the outside players and then switch play to the team in the other square. If the pressing team wins it first, they switch play to the far square straight away; the team that lost it becomes the defenders, 3 moving into the other square and 1 into the neutral zone, and the outside players move across too.', 'Possession target 4 passes before switching. Continuous play; swap the outside team often.', NULL, 'Talk to press as a unit and cover each other, show the opponent inside or outside, force play onto the weaker foot, change attitude instantly on winning or losing it.', '10-16 players (4 teams of 4)', 10, 16, '2 squares 25 x 25 metres + 7 metre neutral zone', 57.0, 25.0, 12.5, false, false, false, NULL, 70),
  ('Three-team press, switch and fast break', 'transition', 'opposed', 'out_of_possession', 198, 198, 'Wednesday Practice 2 (Sectorial)', NULL, 'Pressing as a collective unit to stop forward passes, then attacking the goal quickly after winning the ball.', '30 x 50 m area with two end zones, a goal and GK at each end and a neutral zone in the middle; blues (4+GK) in zone 1 v 3 yellows, reds in zone 2, one extra yellow in the neutral zone.', 'Coach serves into zone 1; blues try to make 5 passes and switch to the reds in zone 2, with the neutral yellow trying to cut out the switch. If the switch arrives, yellows move to defend in zone 2 and reds aim for 5 passes and switch back. If yellows win the ball before a switch, they attack the reds'' goal as fast as possible.', '5 passes before switching. When yellows win it they can go anywhere; reds and blues stay in their zones. Rotate team roles every 2 minutes.', NULL, 'Create a pressing zone round the ball, close horizontal and vertical lanes, show inside or outside, force the weak foot, switch attitude immediately on regains.', '12-15 outfield players + 2 GKs', 14, 17, '30 x 50 metres / 34 x 55 yards (including neutral zone)', 50.0, 30.0, 12.0, true, true, true, NULL, 80),
  ('Win it and go wide 4v2 break', 'transition', 'opposed', 'to_attack', 199, 199, 'Wednesday Practice 3 (Intersectorial)', NULL, 'After winning possession, get the ball out to a winger quickly and attack with an overload (4v2).', 'Pitch split into a low zone, middle zone and high zone with a goal and GK at each end; start with 2v1 in each end zone and 3v3 plus 2 neutral wingers (yellows) in the middle.', 'The reds start from their keeper with a 2v1 in their low zone and play into the middle; a centre back steps up to make 6v3 with the wingers, then they try to create a 4v2 in the high zone with both wingers and a midfielder pushing on. Whenever the blues win the ball they go wide to a winger fast and launch their own 4v2 break while the reds stay in their zones until the attack ends.', 'Players restricted to their zones except the advancing centre back, the 2 wingers and one midfielder. Restart from a goalkeeper after every finish or ball out.', NULL, 'Play forward and wide quickly on a regain; press the ball and its area; stop forward passes in behind; switch attitude instantly.', '14-18 outfield players + 2 GKs', 16, 20, NULL, NULL, NULL, 15.0, true, true, true, NULL, 90),
  ('3v3+3 possession, five passes scores', 'rondo', 'overload', 'in_possession', 201, 201, 'Thursday (1 match week) Practice 1', NULL, 'Fast ball circulation and switching play using a third man to set the ball back.', '20 x 25 m box with three teams of three; one team defends inside, the two others keep the ball with two on the sides and one inside each.', 'Coach serves in; the two attacking teams keep possession, scoring a point for every five passes in a row. Whoever loses the ball swaps in as defenders.', 'No pass straight back to the passer - always find a third man; all four sides must stay occupied, outside players may swap; outside 1 touch, inside 2 touches.', 'Can be played with teams of four.', 'Drop deep, push up, move inside/outside to make triangles; open body shape and look far before receiving.', '3v3+3 (9-12 players)', 9, 12, '20 x 25 metres / 22 x 27 yards', 25.0, 20.0, 12.0, false, false, false, NULL, 100),
  ('Two-group possession, switch fullback to fullback', 'positional_game', 'overload', 'in_possession', 202, 202, 'Thursday (1 match week) Practice 2 (Collective)', NULL, 'Circulate the ball quickly and switch play from one side to the other through the midfield.', '20 x 50 m area split into two zones with a neutral zone in the middle; three teams of six. Reds defend with three per zone; yellows have two inside and one outside each zone; blues sit outside in roles (2 CBs one side, fullbacks at opposite ends, 2 CMs in the neutral zone).', 'Coach starts; blues and yellows try to move the ball from one fullback to the other via the central midfielders for a point. If reds win it, the losing team becomes defenders.', 'No passing straight back to the passer (third man); outside players 1 touch, inside players 2 touches.', NULL, 'Receive on the half-turn with a directional first touch forwards; keep switching positions and making triangles.', '3 teams of 6 (15-18 players)', 15, 18, '20 x 50 metres / 22 x 55 yards incl. neutral zone', 50.0, 20.0, 15.0, false, false, true, NULL, 110),
  ('Build-up overloads vs compact 4-4 block', 'phase_of_play', 'opposed', 'in_possession', 203, 203, 'Thursday (1 match week) Practice 3 (Collective)', NULL, 'Build from the goalkeeper and switch play to create a 2v1 out wide against the opponent''s fullback.', 'Pitch marked in 5 vertical channels; blues in 4-2-3-1 / 4-3-3 with GK, reds in a 4-4 middle block. Two wide end zones (a 2v1 side and a 1v1 side) with a mini goal each.', 'Keeper starts; blues use set passing patterns, must get the ball through all 5 channels, then enter a side zone and score in its mini goal. Reds press compactly; if they win it they try to hit the blue keeper''s goal.', 'Ball must visit all 5 channels before entering a side zone; only one blue in the 1v1 zone, two in the 2v1 zone; only the red fullback defends there. Ball out = restart from keeper.', 'Change the passing pattern each set, free choice in the final set.', 'Blues stay compact after losing it and press to force mistakes and win it back fast.', '11 v 8 approx.', NULL, NULL, NULL, NULL, NULL, 15.0, true, true, true, NULL, 120),
  ('Build-up overloads vs 3-4-1, four zones', 'small_sided_game', 'opposed', 'in_possession', 204, 204, 'Thursday (1 match week) Practice 4 (Collective)', NULL, 'Play out from the back and create a 2v1 on the right back or exploit space between left CB and wing back.', 'Pitch with four zones from two horizontal red lines and three central channels; goals at both ends, pole gates in the wide end zones (one 2v1 side, one 1v1 side).', 'Coach serves; blues must pass through all 3 central channels before scoring by passing or dribbling through a gate (1 pt) or scoring in the big goal (2 pts). Reds counter if they win it.', 'All outfield players within 2 horizontal zones; offside in the final zone; red defenders may use only 2 channels at a time. Blues counter-press after loss, then use a direct attack if they regain.', NULL, 'Mix short and long passes; open body shape; time runs behind the line; stay compact.', 'Full teams with GKs', NULL, NULL, NULL, NULL, NULL, 30.0, true, true, true, NULL, 130),
  ('Drop off and stop balls in behind, 3v5', 'defending', 'overload', 'to_defend', 206, 206, 'Friday (1 match week) Practice 1 (Sectorial)', NULL, 'Defenders drop off and stop the opposition playing in behind, then transition to attack.', '45 x 35 m area in three channels with a big goal and GK; 5 reds (AM, CM, F, two wingers) v 3 blue defenders; 4 mini goals along the halfway line for the blues.', 'Coach starts; red CM and AM combine then play a deep ball to a winger and everyone moves. Reds have 6 seconds to score; blues win it and score in a mini goal. Coach then serves a second ball to the blues for 20 seconds of transition play.', 'Blues may not defend in the side channels; offside on; reds 6 seconds to finish.', NULL, 'Mark while seeing ball, space and goal; block and track runs; cover the central channel first.', '5 v 3 + GK', 9, 9, '45 x 35 metres / 50 x 40 yards', 45.0, 35.0, 4.0, true, true, true, NULL, 140),
  ('Drop off and stop balls in behind, 5v5', 'defending', 'opposed', 'to_defend', 207, 207, 'Friday (1 match week) Practice 2 (Sectorial)', NULL, 'Same drop-off defending as the 3v5 version with equal numbers and more room to counter.', 'Half pitch in three channels with GK; two blue fullbacks added so it is 5v5 outfield; mini goals for the blues.', 'Red CM and AM combine and play deep to a winger; all move to attack/defend. Reds have 6 seconds to score; coach then gives a second ball to the blues for 20 seconds of transition actions.', 'Blue fullbacks may defend in all channels; reds 6 seconds to score.', 'Progression of the 3v5 practice.', 'Correct defensive body shape, blind-side runs and second-ball awareness on the counter.', '5 v 5 + GK (8-10 outfield + 1 GK)', 9, 11, 'Half pitch', NULL, NULL, 4.0, true, true, true, NULL, 150),
  ('Drop off, compact, counter with switch', 'transition', 'opposed', 'to_attack', 208, 208, 'Friday (1 match week) Practice 3 (Intersectorial)', NULL, 'Drop off compactly to win the ball, then switch with a deep diagonal to the far winger and counter fast.', '55 m x half pitch in three equal horizontal zones, goal and GK at each end; reds in 4-2, blues in 4-2-3-1 or 4-3-3.', 'Coach passes to a red defender; reds attack, blue back four and midfield drop and stay compact. On winning it the blues switch with a diagonal to the opposite winger and have 5 seconds to score.', 'All players within 2 zones; reds 2 touches; offside in the final zone; restart with coach to reds; swap the blue back four halfway.', NULL, 'Switch to the side away from where the ball was won.', '16-20 outfield + 2 GKs', 18, 22, '55 metres / 60 yards x half pitch length', 55.0, NULL, 7.0, true, true, true, NULL, 160),
  ('8v6 possession then 3v2 break', 'transition', 'overload', 'to_attack', 210, 210, 'Saturday (1 match week) Practice 1 (Collective)', NULL, 'Keep the ball and switch play; on regain, break fast into a 3v2.', 'Box split into two halves plus a 3v2 final zone with goal. Blues: CB, FB, CM in each half plus 2 wingers outside; reds: CM and forward/AM per half, 2 CBs and 2 fullbacks outside.', 'Red GK starts; reds keep it and switch fullback to fullback for a point. Blues press, win it and find a winger, then go 3v2 against the red CBs with one extra blue joining; 5 seconds to finish.', 'No pass back to the passer (third man); outside players may not pass to each other; inside 2 touches, outside 1 touch.', NULL, 'Collective pressing; quick forward ball to a winger after winning it.', '14-18 players', 14, 18, NULL, NULL, NULL, 8.0, true, true, true, NULL, 170),
  ('Wide 2v1 overloads in 8v8+3 zonal game', 'small_sided_game', 'overload', 'in_possession', 211, 211, 'Saturday (1 match week) Practice 2 (Collective)', NULL, 'Attack the opposition right back by creating a 2v1 with winger and fullback.', '40 x 60 m with goals and GKs; two teams of back 4, CM, AM, F plus 3 yellow neutrals (CM and 2 wingers); 4 side zones only fullbacks and wingers may enter.', 'Coach serves; team in possession builds and finds a neutral winger in a 2v1 side zone, who combines with the fullback and plays into the centre to score. Defending team counters if it wins it.', 'Only fullbacks and wingers in side zones; a fullback may push forward when his team attacks that zone; no offside; restart from coach.', NULL, 'Triangles, swapping positions and switching side to side.', '8v8+3 (18-20 outfield + 2 GKs)', 20, 22, '40 x 60 metres / 44 x 65 yards', 60.0, 40.0, 10.0, true, true, true, NULL, 180),
  ('Defend corners then counter 4v2', 'set_piece', 'opposed', 'set_piece', 212, 212, 'Saturday (1 match week) Practice 3 (Collective)', NULL, 'Defend a corner and launch a quick counter-attack after winning it.', 'Half pitch + 10 yards split in two halves, goal at each end; blues defend a corner with 10 and keep a forward up; reds have 6 attackers on the corner and 2 defenders in the other half.', 'Red corner; if reds score they go again. If blues win it the back four push up and 3 blues join the forward to attack 4v2, finishing within 5 seconds. If reds win the first ball the coach serves a second for another 4v2.', 'Counter must finish within 5 seconds.', NULL, 'Offer support in front and behind; make the first pass easy; time runs to stay onside.', '14-18 outfield + 2 GKs', 16, 20, 'Half pitch + 10 yards', NULL, NULL, NULL, true, true, true, NULL, 190),
  ('Back four vs 3-5-2 in four zones', 'defending', 'overload', 'out_of_possession', 219, 219, 'Monday (2 match week) Practice 1 (Sectorial)', NULL, 'Back four coordination - compact, covering and shifting - against a 3-5-2.', '50 x 45 m in four zones (quarters); red GK and goal, 4 mini goals for reds to attack; reds in 3-5-2, blues back 4 + 2 forwards; 2 yellow jokers.', 'Red GK starts; reds use their overload to build and score in a mini goal. Blues defend, and on winning it may roam all zones to counter with the jokers into the big goal.', 'Red middle CB and AM roam their half; all others stay in their zone; jokers free everywhere for the team in possession.', NULL, 'Communicate and swap markers; take half-and-half positions to cover space.', '16-20 outfield + 1 GK', 17, 21, '50 x 45 metres / 55 x 50 yards', 50.0, 45.0, 10.0, true, true, true, NULL, 200),
  ('Centre backs shift across to cover', 'defending', 'overload', 'out_of_possession', 220, 220, 'Monday (2 match week) Practice 2 (Sectorial)', NULL, 'Centre backs slide into the next zone to cover and level numbers.', '55 x 45 m in four zones with a big goal and GK; 3 mini goals for blues; reds in 4-4-2 locked in zones; blues back 4 + 2 wingers inside, 2 forwards outside; 2 yellow jokers.', 'Coach passes to a red defender; reds build with joker help and shoot from inside the zones. A blue CB shifts to make it 3v3. On winning it the blues counter freely using jokers and forwards, who lay off with one touch.', 'Players stay in zones except blue CBs; reds must shoot from inside the zones; restart from coach.', NULL, 'Communicate, switch markers, half-and-half positions.', '18-20 outfield + 1 GK', 19, 21, '55 x 45 metres / 60 x 50 yards', 55.0, 45.0, 10.0, true, true, true, NULL, 210),
  ('Force play to the weak centre back', 'defending', 'opposed', 'out_of_possession', 221, 221, 'Monday (2 match week) Practice 3 (Intersectorial)', NULL, 'Direct the opponent''s build-up towards their weaker left CB and press together to force mistakes.', '55 x 60 m in three equal thirds with channel guide lines; reds in 3-5-2 with GK, blues in 4-2-3-1 / 4-3-3 with GK. Thirds: 2v3, 4v5, 4v2.', 'Red GK starts and reds try to build through the thirds and score. Blues shape their press to steer play to the red left CB, win it, then counter freely to score.', 'Players stay in their thirds until blues regain; offside in the final thirds only; restart from red GK.', NULL, 'Starting positions, switch markers, recognise pressing cues.', '22 players', 22, 22, '55 x 60 metres / 60 x 65 yards', 60.0, 55.0, 10.0, true, true, true, NULL, 220),
  ('Build to goal zone, then press', 'phase_of_play', 'opposed', 'in_possession', 223, 223, 'Tuesday (2 match week) Practice 1 (Collective)', NULL, 'Play out to midfield against a 3-5-2 and react instantly to win the ball back.', 'Half pitch + 10 yards, 5 channel lines and a goal zone near halfway; blues 4-3 with GK, reds 5-2.', 'Blue GK starts; blues build and score by receiving in the goal zone. Reds press high and counter if they win it. After a blue score the coach serves to reds and blues must counter-press immediately.', 'Blues score by receiving in the goal zone.', NULL, 'Triangles, rotations, speed of play; create a pressure zone round the ball after losing it.', '14-17 outfield + 1 GK', 15, 18, 'Half pitch + 10 yards', NULL, NULL, 5.0, true, true, true, NULL, 230),
  ('Overloads vs 3-5-2, cross, then defend', 'phase_of_play', 'opposed', 'in_possession', 224, 224, 'Tuesday (2 match week) Practice 2 (Collective)', NULL, 'Build up and create wide 2v1s against a 3-5-2, cross to score, then transition to defend.', 'Two thirds of the pitch; blues 4-2-3-1 / 4-3-3 with GK, reds 3-5-2 with goal; low zone 4v2 and two wide 2v1 side zones.', 'Blue GK starts; CMs drop for a 4v2, then move the ball to a side zone for a 2v1 and cross to score. After a score the coach gives reds a new ball and blues must create a pressure zone.', NULL, NULL, 'Quick reactions to transition; stop the opponent playing forward.', '22 players', 22, 22, '2/3 of full pitch', NULL, NULL, 5.0, true, true, true, NULL, 240),
  ('Defend crosses and second balls 7v7+4', 'defending', 'overload', 'out_of_possession', 225, 225, 'Tuesday (2 match week) Practice 3 (Collective)', NULL, 'Defend crosses, win second balls and counter quickly.', 'Two thirds of the pitch with goals and GKs, 5 channel guides; 4 yellow neutral wingers in side zones only they enter.', 'A keeper starts; team in possession plays to a winger in a side zone to cross. Blues defend crosses and second balls; if they win it or it goes out the coach serves reds for a quick counter.', 'Goal counts only from a winger''s cross (first or second ball); others may only enter side zones after the ball does.', NULL, 'Body shape facing ball and man, block and track runs, shift collectively.', '7v7+4 (16-18 outfield + 2 GKs)', 18, 20, '2/3 of full pitch', NULL, NULL, 5.0, true, true, true, NULL, 250),
  ('Switch to the weak side zonal game', 'positional_game', 'overload', 'in_possession', 227, 227, 'Thursday (2 match week) Practice 1 (Sectorial)', NULL, 'Win the ball in a side zone and switch quickly to overload the weak side.', 'Half pitch with big goal and GK, 3 mini goals; side zones and middle zone; 3v3 start in one side zone.', 'Coach serves to red FB and 2 yellow neutrals who keep it; blue LB, CM and LW win it and pass to the central CM, who switches to create a 2v1 on the far side (overlap and cross). Two forwards attack the box. Red CBs counter into the mini goals if they win it.', NULL, 'Restart with the 3v3 in the other side zone and switch the other way.', 'Speed of play, overlaps, finishing positions, tight marking after losing it.', '14-16 outfield + 1 GK', 15, 17, 'Half pitch', NULL, NULL, 5.0, true, true, true, NULL, 260),
  ('Build up vs high 4-2, then press', 'phase_of_play', 'opposed', 'in_possession', 228, 228, 'Thursday (2 match week) Practice 2 (Intersectorial)', NULL, 'Build up and create overloads against a 4-4-2 high block, then transition to defend.', 'Half pitch with goal zone; blues GK, back 4 and 2 CMs; reds press high with midfield 4 and 2 forwards; 5 channel guides.', 'Blue GK starts with coach-set patterns; blues score by receiving in the goal zone. Coach then gives reds a new ball and blues counter-press; if reds win it first they counter at once.', NULL, NULL, 'Positional play, rotations, pressure zone on loss.', '12-16 outfield + 1 GK', 13, 17, 'Half pitch', NULL, NULL, 5.0, true, true, true, NULL, 270),
  ('9v9 two-zone build-up overloads', 'small_sided_game', 'opposed', 'in_possession', 229, 229, 'Thursday (2 match week) Practice 3 (Intersectorial)', NULL, 'Build up and create 5v4 overloads against a 4-4-2 high block.', 'Narrow half pitch + 10 yards in two halves with 3 channels; goals and GKs at both ends.', 'Blue GK starts in zone 1; CM drops for a 5v4 and switches to the winger in zone 2. Once in zone 2 both fullbacks push on for another 5v4 (overlap and cross). Reds counter freely if they win it.', 'Zone restrictions until reds regain, then none.', NULL, 'Quick reactions to transition, stop the opponent playing forward.', '9v9 (16-20 outfield + 2 GKs)', 18, 22, 'Half pitch (narrower) + 10 yards', NULL, NULL, 5.0, true, true, true, NULL, 280),
  ('Defend long ball to two forwards', 'defending', 'opposed', 'out_of_possession', 231, 231, 'Friday (2 match week) Practice 1 (Sectorial)', NULL, 'Defend direct play into two forwards and win the second ball.', 'Central area marked; 2 blue CBs v 2 red forwards; CMs waiting outside; 2 yellow neutral wingers; goal and GK; players work in pairs.', 'Coach plays a long diagonal into the area; CBs and forwards duel and both CMs go for the second ball. Winner attacks 5v3 with the wingers; reds have 6 seconds. Blues win it and break with a forward or wide first pass. Coach then serves a second ball for 20 seconds of transition.', 'Offside on; 6 seconds to score; first pass after regain forward or wide.', NULL, 'Drop off, correct body shape, second-ball awareness, blind-side runs.', 'Pairs + 1 GK', NULL, NULL, NULL, NULL, NULL, 4.0, true, true, true, NULL, 290),
  ('Defend long ball, 7v7 second balls', 'defending', 'opposed', 'out_of_possession', 232, 232, 'Friday (2 match week) Practice 2 (Sectorial)', NULL, 'Back four defends direct balls into two forwards and wins the second ball in a bigger game.', 'Larger area 6v6 plus GK; central zone; reds with wingers and CMs.', 'Red CM plays a long diagonal to a forward; CBs duel, all CMs chase the second ball. Winner attacks; reds 6 seconds using wingers. Blues regain and break forward/wide, then coach serves a second ball for 20 seconds of transition.', 'Offside on; 6 seconds to score.', 'Progression of the previous practice.', 'Back four coordination, correct body shape, second-ball awareness.', '7 v 7', NULL, NULL, NULL, NULL, NULL, 4.0, true, true, true, NULL, 300),
  ('Transitions 5(+4) v 5(+4) game', 'transition', 'overload', 'to_attack', 233, 233, 'Friday (2 match week) Practice 3 (Intersectorial)', NULL, 'Switch attitude fast between attack and defence; first pass after winning it must go forward.', '35 m wide x double penalty-box depth, goals with GKs; 4v4 inside plus 4 outside support players per team.', 'A keeper starts; team in possession uses its outside players for an 8v4 to build and score. Defenders press together, win it and play forward at once to break and score quickly.', 'First pass after regain must be forward; outside players 2 touches and can be pressed by inside players.', 'Outside players may enter when their team wins it, to overload the counter.', 'Open passing lines, stop the opponent playing forward, force them onto the weaker foot.', '5(+4) v 5(+4) (16-18 outfield + 2 GKs)', 18, 20, '35 metres / 40 yards x double penalty box depth', NULL, 35.0, 4.0, true, true, true, NULL, 310),
  ('Third-man runs, zonal 11v7', 'phase_of_play', 'overload', 'in_possession', 235, 235, 'Saturday (2 match week) Practice 1 (Collective)', NULL, 'Midfielders make timed third-man runs from deep to receive in behind.', '70 x 60 m with 5 channel guides; blues with GK build against a red 4-4-2 (4-2) with GK; scoring zone at the far end.', 'Blue GK starts; blues build and midfielders run beyond to receive in the scoring zone and finish 1v1 against the red keeper. Reds counter quickly if they win it.', NULL, NULL, 'Triangles, rotations, speed; pressure zone after loss.', '11v7 (14-16 outfield + 2 GKs)', 16, 18, '70 x 60 metres / 75 x 65 yards', 70.0, 60.0, 12.0, true, true, true, NULL, 320),
  ('Team press vs 4-4-2, 10v9', 'defending', 'opposed', 'out_of_possession', 236, 236, 'Saturday (2 match week) Practice 2 (Collective)', NULL, 'Press together to make play predictable and push the opponent outside.', '60 x 65 m in two halves, red GK and goal, 3 mini goals for blues; reds 4-2 with 5 per half, blues 4-3-3 / 4-2-3-1 free to move.', 'Red GK starts; reds build into zone 2 and score in the mini goals. Blues press by ball position to steer play outside, win it and counter quickly into the big goal.', 'Reds stay in their zone; blues free across both.', NULL, 'Starting positions, swap markers, half-and-half positions, read pressing cues.', '10v9 (18-20 outfield + 1 GK)', 19, 21, '60 x 65 metres / 65 x 70 yards', 65.0, 60.0, 10.0, true, true, true, NULL, 330),
  ('Team press vs 4-4-2, 10v11 full width', 'defending', 'opposed', 'out_of_possession', 237, 237, 'Saturday (2 match week) Practice 3 (Collective)', NULL, 'Same collective press, now across the full pitch width against added wingers.', 'Half pitch + 10 yards full width, two zones, 5 channel guides; reds add 2 wingers.', 'As the 10v9: reds build to score in the mini goals; blues press to steer play, win it and counter.', 'Same zone rules as the previous practice.', 'Progression of the 10v9 game.', 'Pressing all together; recognise cues to press.', '10v11 (20 outfield + 1 GK)', 21, 21, 'Half pitch + 10 yards', NULL, NULL, 10.0, true, true, true, NULL, 340)
) AS v(t, cat, opp, m, pf, pt, ref, coach, obj, setup, proc, rules, prog, cp, players, mn, mx, area, len, wid, dur, goals, gk, dir, age, so)
